      totalStudents: [
        { $count: "count" }
      ],
      averageAge: [
        { $group: { _id: null, avgAge: { $avg: "$age" } } }
      ],
      cityWise: [
        { $group: { _id: "$city", total: { $sum: 1 } } }
      ]
    }
  }
])

